insert into public.recipes (
  source_key, name, normalized_name, symbol, preparation_minutes,
  vegetarian, contains_pork, kid_friendly, healthy, budget_tier
)
select
  source_key, name, normalized_name, symbol, preparation_minutes,
  vegetarian, contains_pork, kid_friendly, healthy, budget_tier
from recipe_seed_data
on conflict (source_key) do update set
  name = excluded.name,
  normalized_name = excluded.normalized_name,
  symbol = excluded.symbol,
  preparation_minutes = excluded.preparation_minutes,
  vegetarian = excluded.vegetarian,
  contains_pork = excluded.contains_pork,
  kid_friendly = excluded.kid_friendly,
  healthy = excluded.healthy,
  budget_tier = excluded.budget_tier,
  updated_at = now();

commit;
